-- NÉP 015: service inclusions/exclusions for the original 10 sample tours.
-- These are presentation estimates, not supplier confirmations or a binding offer.
with plans(title,inclusions,exclusions) as (values
('Sài Gòn qua những lớp ký ức',array['Hướng dẫn viên tiếng Việt theo tuyến','Nước uống đóng chai','Tài liệu giới thiệu các điểm dừng'],array['Xe đưa đón đến điểm tập trung','Bữa ăn chính và đồ uống gọi thêm','Vé tham quan có thu phí (nếu phát sinh)','Chi tiêu cá nhân']),
('Một ngày ở Củ Chi: đất và người',array['Xe du lịch theo chương trình khứ hồi từ điểm hẹn TP.HCM','Hướng dẫn viên tiếng Việt','01 bữa trưa theo thực đơn đoàn','Nước uống trên xe'],array['Chi tiêu cá nhân và đồ uống ngoài thực đơn','Vé tham quan nếu chưa ghi rõ trong xác nhận cuối','Phụ thu đón ngoài khu vực quy định']),
('Miền vườn Cái Bè – chậm một nhịp',array['Xe du lịch theo chương trình','Hướng dẫn viên tiếng Việt','Các hoạt động vườn/đò theo lịch được xác nhận','Bữa ăn theo thực đơn chương trình','Nước uống'],array['Chi tiêu cá nhân','Mua sắm đặc sản','Dịch vụ phát sinh ngoài lịch đã xác nhận']),
('Đà Lạt – dấu chân cao nguyên',array['Xe du lịch theo tuyến và điểm đón xác nhận','02 đêm khách sạn tiêu chuẩn dự kiến','02 bữa sáng và các bữa chính ghi trong lịch trình','Hướng dẫn viên tiếng Việt','Nước uống trên xe'],array['Phụ thu phòng đơn và nâng hạng phòng','Đồ uống gọi thêm, minibar, giặt ủi','Vé/hoạt động ngoài chương trình','Chi tiêu cá nhân']),
('Hội An – phố nhỏ, chuyện dài',array['Xe du lịch theo phương án khởi hành đã xác nhận','01 đêm khách sạn dự kiến','Bữa ăn theo lịch trình và 01 bữa sáng','Hướng dẫn viên tiếng Việt','Nước uống trên xe'],array['Phụ thu phòng đơn/nâng hạng','Vé tham quan nếu không ghi trong xác nhận dịch vụ','Đồ uống gọi thêm và chi tiêu cá nhân','Hoạt động ngoài chương trình']),
('Huế – sống cùng di sản',array['Xe du lịch theo chương trình','01 đêm khách sạn dự kiến','Bữa ăn theo lịch trình và 01 bữa sáng','Hướng dẫn viên tiếng Việt','Nước uống trên xe'],array['Phụ thu phòng đơn/nâng hạng','Vé di tích nếu không ghi trong xác nhận dịch vụ','Đồ uống gọi thêm và chi tiêu cá nhân','Dịch vụ ngoài chương trình']),
('Hà Nội – ngõ nhỏ và ký ức phố',array['Hướng dẫn viên tiếng Việt theo tuyến đi bộ','Nước uống','Tài liệu giới thiệu tuyến phố'],array['Di chuyển đến điểm hẹn','Bữa ăn và đồ uống','Vé tham quan có thu phí (nếu có)','Chi tiêu cá nhân']),
('Ninh Bình – non nước và làng quê',array['Xe du lịch theo tuyến dự kiến','01 đêm khách sạn dự kiến','Bữa ăn theo lịch trình và 01 bữa sáng','Hướng dẫn viên tiếng Việt','Nước uống trên xe'],array['Phụ thu phòng đơn/nâng hạng','Vé thuyền và vé tham quan nếu không ghi trong xác nhận','Đồ uống gọi thêm','Chi tiêu cá nhân']),
('Sa Pa – bản làng và sắc núi',array['Xe du lịch theo phương án vận chuyển đã xác nhận','02 đêm lưu trú dự kiến','Bữa ăn theo lịch trình và bữa sáng','Hướng dẫn viên/đối tác địa phương theo hoạt động được xác nhận','Nước uống'],array['Phụ thu phòng đơn/nâng hạng','Vé cáp treo hoặc hoạt động tự chọn','Đồ uống gọi thêm và chi tiêu cá nhân','Chi phí phát sinh do thay đổi thời tiết/yêu cầu riêng']),
('Hà Giang – cung đường đá và bản sắc',array['Xe du lịch có lái xe đủ điều kiện theo tuyến được thẩm định','03 đêm lưu trú dự kiến','Bữa ăn theo lịch trình','Hướng dẫn viên tiếng Việt và hỗ trợ địa phương theo kế hoạch xác nhận','Nước uống'],array['Phụ thu phòng đơn/nâng hạng','Đồ uống gọi thêm và chi tiêu cá nhân','Hoạt động/vé ngoài chương trình','Chi phí phát sinh do thời tiết, giao thông hoặc yêu cầu riêng'])
)
update public.journeys j set inclusions=p.inclusions, exclusions=p.exclusions
from plans p where j.title=p.title;
